import (
	context "context"
	fern "github.com/go-nullable-date-ref/fern"
	fernclient "github.com/go-nullable-date-ref/fern/client"
)

client := fernclient.NewClient()
response, err := client.Reports.Create(
	context.TODO(),
	&fern.Report{
		CreatedDate: fern.MustParseDate(
			"2023-01-15",
		),
		Title: "title",
	},
)
